SELECT spread_id, order_id, order_no, fabric_id, fabric_no, fabric_name, color_name, require_layers, require_length, actual_layers, actual_length, status, issued_flag, remark, create_user_name, create_time FROM t_fabric_spread
deleted_flag = 0
AND INSTR(order_no, #{queryForm.orderNo})
AND status = #{queryForm.status}
AND issued_flag = #{queryForm.issuedFlag}
ORDER BY spread_id DESC
